/// Raven `WP_SaberBladeLength`.
///
/// Source: `oracle/oracle/codemp/game/w_saber.c:2779-2791`
pub fn WP_SaberBladeLength(
    saber: *mut saberInfo_t,
) -> f32 {
    // return largest length
    unsafe {
        let mut len = 0.0f32;
        for i in 0..(*saber).numBlades {
            if (*saber).blade[i as usize].lengthMax > len {
                len = (*saber).blade[i as usize].lengthMax;
            }
        }
        len
    }
}

/// Raven `WP_SaberLength`.
///
/// Source: `oracle/oracle/codemp/game/w_saber.c:2793-2813`
pub fn WP_SaberLength(
    ent: *mut gentity_t,
) -> f32 {
    // return largest length
    unsafe {
        if ent.is_null() || (*ent).client.is_null() {
            return 0.0f32;
        }
        let client = (*ent).client as *mut gclient_t;
        let mut best_len = 0.0f32;
        for i in 0..MAX_SABERS as usize {
            let len = WP_SaberBladeLength(&mut (*client).saber[i]);
            if len > best_len {
                best_len = len;
            }
        }
        best_len
    }
}

